-- V4: Pharma compliance overlays on the drug master.
--
-- 1) Schedule H1 (Drugs and Cosmetics Rules, 1945 — Schedule H1 as amended):
--    the 46 notified substances (3rd/4th gen cephalosporins, carbapenems,
--    anti-TB drugs, tramadol, benzodiazepines, zolpidem, codeine, ...).
--    Matching rows get drug_schedule = 'H1' and prescription_required = true.
--    Matching is by substance name within the salt composition, so combination
--    products containing an H1 substance are covered too.
--
-- 2) The 36 lifesaving drugs made GST-exempt by the 56th GST Council
--    (33 from 12%% -> nil + 3 from 5%% -> nil, eff. 2025-09-22) are seeded as
--    reference rows at gst_rate = 0. The exemption is BY DRUG NAME, not HSN.

UPDATE drug_master
SET drug_schedule = 'H1', prescription_required = true
WHERE lower(salt_composition) LIKE '%alprazolam%' OR lower(generic_name) LIKE '%alprazolam%' OR lower(salt_composition) LIKE '%balofloxacin%' OR lower(generic_name) LIKE '%balofloxacin%' OR lower(salt_composition) LIKE '%buprenorphine%' OR lower(generic_name) LIKE '%buprenorphine%' OR lower(salt_composition) LIKE '%capreomycin%' OR lower(generic_name) LIKE '%capreomycin%' OR lower(salt_composition) LIKE '%cefdinir%' OR lower(generic_name) LIKE '%cefdinir%' OR lower(salt_composition) LIKE '%cefditoren%' OR lower(generic_name) LIKE '%cefditoren%' OR lower(salt_composition) LIKE '%cefepime%' OR lower(generic_name) LIKE '%cefepime%' OR lower(salt_composition) LIKE '%cefetamet%' OR lower(generic_name) LIKE '%cefetamet%' OR lower(salt_composition) LIKE '%cefixime%' OR lower(generic_name) LIKE '%cefixime%' OR lower(salt_composition) LIKE '%cefoperazone%' OR lower(generic_name) LIKE '%cefoperazone%' OR lower(salt_composition) LIKE '%cefotaxime%' OR lower(generic_name) LIKE '%cefotaxime%' OR lower(salt_composition) LIKE '%cefpirome%' OR lower(generic_name) LIKE '%cefpirome%' OR lower(salt_composition) LIKE '%cefpodoxime%' OR lower(generic_name) LIKE '%cefpodoxime%' OR lower(salt_composition) LIKE '%ceftazidime%' OR lower(generic_name) LIKE '%ceftazidime%' OR lower(salt_composition) LIKE '%ceftibuten%' OR lower(generic_name) LIKE '%ceftibuten%' OR lower(salt_composition) LIKE '%ceftizoxime%' OR lower(generic_name) LIKE '%ceftizoxime%' OR lower(salt_composition) LIKE '%ceftriaxone%' OR lower(generic_name) LIKE '%ceftriaxone%' OR lower(salt_composition) LIKE '%chlordiazepoxide%' OR lower(generic_name) LIKE '%chlordiazepoxide%' OR lower(salt_composition) LIKE '%clofazimine%' OR lower(generic_name) LIKE '%clofazimine%' OR lower(salt_composition) LIKE '%codeine%' OR lower(generic_name) LIKE '%codeine%' OR lower(salt_composition) LIKE '%cycloserine%' OR lower(generic_name) LIKE '%cycloserine%' OR lower(salt_composition) LIKE '%diazepam%' OR lower(generic_name) LIKE '%diazepam%' OR lower(salt_composition) LIKE '%diphenoxylate%' OR lower(generic_name) LIKE '%diphenoxylate%' OR lower(salt_composition) LIKE '%doripenem%' OR lower(generic_name) LIKE '%doripenem%' OR lower(salt_composition) LIKE '%ertapenem%' OR lower(generic_name) LIKE '%ertapenem%' OR lower(salt_composition) LIKE '%ethambutol%' OR lower(generic_name) LIKE '%ethambutol%' OR lower(salt_composition) LIKE '%ethionamide%' OR lower(generic_name) LIKE '%ethionamide%' OR lower(salt_composition) LIKE '%faropenem%' OR lower(generic_name) LIKE '%faropenem%' OR lower(salt_composition) LIKE '%gemifloxacin%' OR lower(generic_name) LIKE '%gemifloxacin%' OR lower(salt_composition) LIKE '%imipenem%' OR lower(generic_name) LIKE '%imipenem%' OR lower(salt_composition) LIKE '%isoniazid%' OR lower(generic_name) LIKE '%isoniazid%' OR lower(salt_composition) LIKE '%levofloxacin%' OR lower(generic_name) LIKE '%levofloxacin%' OR lower(salt_composition) LIKE '%meropenem%' OR lower(generic_name) LIKE '%meropenem%' OR lower(salt_composition) LIKE '%midazolam%' OR lower(generic_name) LIKE '%midazolam%' OR lower(salt_composition) LIKE '%moxifloxacin%' OR lower(generic_name) LIKE '%moxifloxacin%' OR lower(salt_composition) LIKE '%nitrazepam%' OR lower(generic_name) LIKE '%nitrazepam%' OR lower(salt_composition) LIKE '%pentazocine%' OR lower(generic_name) LIKE '%pentazocine%' OR lower(salt_composition) LIKE '%prulifloxacin%' OR lower(generic_name) LIKE '%prulifloxacin%' OR lower(salt_composition) LIKE '%pyrazinamide%' OR lower(generic_name) LIKE '%pyrazinamide%' OR lower(salt_composition) LIKE '%rifabutin%' OR lower(generic_name) LIKE '%rifabutin%' OR lower(salt_composition) LIKE '%rifampicin%' OR lower(generic_name) LIKE '%rifampicin%' OR lower(salt_composition) LIKE '%sodium para-aminosalicylate%' OR lower(generic_name) LIKE '%sodium para-aminosalicylate%' OR lower(salt_composition) LIKE '%sparfloxacin%' OR lower(generic_name) LIKE '%sparfloxacin%' OR lower(salt_composition) LIKE '%thiacetazone%' OR lower(generic_name) LIKE '%thiacetazone%' OR lower(salt_composition) LIKE '%tramadol%' OR lower(generic_name) LIKE '%tramadol%' OR lower(salt_composition) LIKE '%zolpidem%' OR lower(generic_name) LIKE '%zolpidem%';

-- Nil-rated lifesaving drugs (gst_rate 0, identified by molecule name)
ON CONFLICT DO NOTHING;
